BEGIN;
ALTER TABLE public.api_grants ADD COLUMN daily_limit integer CHECK(daily_limit>=0), ADD COLUMN daily_used integer NOT NULL DEFAULT 0, ADD COLUMN daily_on varchar(10);
ALTER TABLE public.member_api_shares ADD COLUMN daily_limit integer CHECK(daily_limit>=0), ADD COLUMN daily_used integer NOT NULL DEFAULT 0, ADD COLUMN daily_on varchar(10);

ALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS shared_team_ids json NOT NULL DEFAULT '[]', ADD COLUMN IF NOT EXISTS quota_team_id integer, ADD COLUMN IF NOT EXISTS audio_bytes bigint NOT NULL DEFAULT 0;
CREATE TABLE public.device_sessions (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id integer NOT NULL REFERENCES public.invite_sessions(id) ON DELETE CASCADE, token_hash varchar(64) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX device_sessions_user ON public.device_sessions(user_id);
CREATE TABLE public.teams (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(80) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.team_members (team_id integer NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE, user_id integer NOT NULL REFERENCES public.invite_sessions(id) ON DELETE CASCADE, role varchar(16) NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')), PRIMARY KEY(team_id,user_id));
CREATE INDEX team_members_user ON public.team_members(user_id);
CREATE TABLE public.invite_teams (invite_code_id integer NOT NULL REFERENCES public.invite_codes(id) ON DELETE CASCADE, team_id integer NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE, PRIMARY KEY(invite_code_id,team_id));
CREATE TABLE public.quota_policies (scope varchar(16) NOT NULL CHECK(scope IN ('platform','default','user','team')), scope_id integer NOT NULL, daily_limit integer CHECK(daily_limit>=0), total_limit integer CHECK(total_limit>=0), concurrent_limit integer CHECK(concurrent_limit>=0), storage_bytes bigint CHECK(storage_bytes>=0), PRIMARY KEY(scope,scope_id));
CREATE TABLE public.quota_reservations (uuid varchar(64) PRIMARY KEY,user_id integer NOT NULL,team_id integer,kind varchar(16) NOT NULL DEFAULT 'generation',cancelled boolean NOT NULL DEFAULT false,bytes bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX quota_reservations_user_date ON public.quota_reservations(user_id,created_at);
CREATE INDEX quota_reservations_team_date ON public.quota_reservations(team_id,created_at);
CREATE TABLE public.external_identities (provider varchar(16) NOT NULL,subject varchar(255) NOT NULL,user_id integer NOT NULL REFERENCES public.invite_sessions(id) ON DELETE CASCADE,PRIMARY KEY(provider,subject));
DO $$ DECLARE legacy_team integer; BEGIN
INSERT INTO public.teams(name) VALUES ('原有团队') RETURNING id INTO legacy_team;
INSERT INTO public.team_members(team_id,user_id) SELECT legacy_team,id FROM public.invite_sessions WHERE team_access OR role='admin';
INSERT INTO public.invite_teams(invite_code_id,team_id) SELECT id,legacy_team FROM public.invite_codes WHERE team_access;
UPDATE public.tasks SET shared_team_ids=json_build_array(legacy_team) WHERE visibility='team';
END $$;
INSERT INTO public.device_sessions(user_id,token_hash,expires_at) SELECT id,token_hash,expires_at FROM public.invite_sessions;
INSERT INTO public.quota_policies(scope,scope_id,daily_limit,concurrent_limit) VALUES ('default',0,3,1);
INSERT INTO public.quota_reservations(uuid,user_id,created_at) SELECT uuid,user_id,coalesce(created_at,now()) FROM public.tasks;
ALTER TABLE public.device_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invite_teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quota_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quota_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.external_identities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.device_sessions,public.teams,public.team_members,public.invite_teams,public.quota_policies,public.quota_reservations,public.external_identities FROM anon,authenticated;
CREATE TABLE public.import_tickets (id varchar(64) PRIMARY KEY,user_id integer NOT NULL REFERENCES public.invite_sessions(id) ON DELETE CASCADE,filename varchar(255) NOT NULL,bytes bigint NOT NULL CHECK(bytes>0 AND bytes<=50000000),state varchar(16) NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.import_tickets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.import_tickets FROM anon,authenticated;
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES ('podcast-imports','podcast-imports',false,50000000,ARRAY['audio/mpeg','audio/wav','audio/x-wav','audio/wave']) ON CONFLICT(id) DO NOTHING;
COMMIT;
